diff --git a/flutter_app/lib/services/attached_session_controller.dart b/flutter_app/lib/services/attached_session_controller.dart
index 7026f6bf16..0508e2a8f7 100644
--- a/flutter_app/lib/services/attached_session_controller.dart
+++ b/flutter_app/lib/services/attached_session_controller.dart
@@ -36,7 +36,16 @@ class AttachedSessionController extends ChangeNotifier {
   /// terminal, forever. The UI shows this instead.
   String? lastSendError;

+  /// Set when the watch saw the primary session file rewritten under it
+  /// (segment rotation, hard-cap truncation, quarantine heal) and the
+  /// tail re-anchored to the new content — rotation drops old history,
+  /// so rows above may describe records no longer in the file; reopening
+  /// shows the authoritative transcript. Sticky: it describes the last
+  /// transition, not the current row batch.
+  String? reanchorNotice;
+
   void _onEvent(AttachedSessionEvent event) {
+    if (event.reanchored) reanchorNotice = sessionReanchorNotice;
     rows.addAll(event.appended);
     notifyListeners();
   }
diff --git a/flutter_app/test/attach/attached_session_controller_test.dart b/flutter_app/test/attach/attached_session_controller_test.dart
index a822a3208d..3ba5e10ce4 100644
--- a/flutter_app/test/attach/attached_session_controller_test.dart
+++ b/flutter_app/test/attach/attached_session_controller_test.dart
@@ -10,8 +10,14 @@ import 'package:flutter_test/flutter_test.dart';
 class _FakeEventSource implements SessionEventSource {
   final _controllers = <String, StreamController<AttachedSessionEvent>>{};

-  void emit(String sessionId, List<AttachedMessage> appended) {
-    _controllers[sessionId]?.add(AttachedSessionEvent(appended: appended));
+  void emit(
+    String sessionId,
+    List<AttachedMessage> appended, {
+    bool reanchored = false,
+  }) {
+    _controllers[sessionId]?.add(
+      AttachedSessionEvent(appended: appended, reanchored: reanchored),
+    );
   }

   @override
@@ -114,6 +120,40 @@ void main() {
     },
   );

+  test(
+    'a re-anchor event surfaces the recovery notice without dropping rows',
+    () async {
+      final events = _FakeEventSource();
+      final controller = AttachedSessionController(
+        sessionId: 'sess-1',
+        title: 'Work session',
+        transport: SessionAttachTransport(
+          events: events,
+          input: _FakeInputChannel(),
+        ),
+      );
+
+      // The primary was rewritten under the watch (rotation / hard cap /
+      // quarantine heal): the notice lands and fresh rows still append.
+      expect(controller.reanchorNotice, isNull);
+      events.emit('sess-1', [
+        const AttachedMessage(role: AttachedMessageRole.user, text: 'new'),
+      ], reanchored: true);
+      await pumpEventQueue();
+      expect(controller.reanchorNotice, sessionReanchorNotice);
+      expect(controller.rows.single.text, 'new');
+
+      // A plain event afterwards does not clear it — the notice
+      // describes the last transition.
+      events.emit('sess-1', []);
+      await pumpEventQueue();
+      expect(controller.reanchorNotice, sessionReanchorNotice);
+
+      controller.dispose();
+      await events.dispose();
+    },
+  );
+
   test(
     'CliSessionPresence reflects the store and notifies on change',
     () async {
